/**
 * Equirectangular projection of [longitude, latitude] into the map viewBox.
 * The offset accounts for the map being clipped at Greenland's northern tip
 * rather than at the pole.
 */
const Y_OFFSET = 17.7;

export function project(lon: number, lat: number): [number, number] {
  return [((lon + 180) / 360) * MAP_W, ((90 - lat) / 180) * (MAP_W / 2) - Y_OFFSET];
}
